using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using StackIt.Core.Simulation;

namespace StackIt.Tests
{
    /// <summary>
    /// Replays every golden vector generated by the Python server simulation. A failure here means
    /// the client would compute a different score than the server and runs would be rejected.
    /// </summary>
    public class SimVectorTests
    {
        public static IEnumerable<string> VectorNames() =>
            Directory.GetFiles(TestPaths.SimVectorsDir(), "*.json")
                .Select(Path.GetFileNameWithoutExtension)
                .OrderBy(n => n);

        [Test]
        public void VectorsExist()
        {
            Assert.GreaterOrEqual(VectorNames().Count(), 10);
        }

        [TestCaseSource(nameof(VectorNames))]
        public void SimulationReproducesVector(string name)
        {
            JObject vector = JObject.Parse(File.ReadAllText(Path.Combine(TestPaths.SimVectorsDir(), name + ".json")));
            Assert.AreEqual(SimConstants.SimVersion, (int)vector["sim_version"]);
            JObject expected = (JObject)vector["expected"];
            var sim = new StackSim((uint)vector["seed"], (bool)vector["continues_allowed"]);

            string error = null;
            try
            {
                // Parse lazily, in order, exactly like the server: the first failing event wins.
                foreach (JToken e in vector["events"])
                    sim.Apply(InputEvent.Parse((int)e["t"], (string)e["type"]));
            }
            catch (InvalidRunException ex)
            {
                error = ex.Code;
            }

            Assert.AreEqual((string)expected["error"], error, "error code");
            if (error != null) return;

            JArray steps = (JArray)expected["steps"];
            Assert.AreEqual(steps.Count, sim.Steps.Count, "step count");
            for (int i = 0; i < steps.Count; i++) AssertStep(steps[i], sim.Steps[i], i);

            JToken final = expected["final"];
            Assert.AreEqual((int)final["score"], sim.Score, "score");
            Assert.AreEqual((int)final["placed"], sim.Placed, "placed");
            Assert.AreEqual((int)final["perfects"], sim.Perfects, "perfects");
            Assert.AreEqual((int)final["max_combo"], sim.MaxCombo, "max_combo");
            Assert.AreEqual((int)final["continues_used"], sim.ContinuesUsed, "continues_used");
            Assert.AreEqual((bool)final["ended"], sim.Ended, "ended");
            Assert.AreEqual((int)final["tick"], sim.Tick, "tick");
        }

        private static void AssertStep(JToken expected, Step actual, int index)
        {
            string at = "step " + index;
            string kind = (string)expected["kind"];
            Assert.AreEqual(kind, KindName(actual.Kind), at + " kind");
            Assert.AreEqual((int)expected["n"], actual.N, at + " n");
            Assert.AreEqual((int)expected["t"], actual.Tick, at + " t");
            Assert.AreEqual((int)expected["score"], actual.Score, at + " score");
            if (kind == "continue") return;

            Assert.AreEqual((string)expected["axis"], actual.Axis == Axis.X ? "x" : "z", at + " axis");
            Assert.AreEqual((int)expected["offset"], actual.Offset, at + " offset");
            if (kind == "miss") return;

            Assert.AreEqual((int)expected["x0"], actual.Block.X0, at + " x0");
            Assert.AreEqual((int)expected["x1"], actual.Block.X1, at + " x1");
            Assert.AreEqual((int)expected["z0"], actual.Block.Z0, at + " z0");
            Assert.AreEqual((int)expected["z1"], actual.Block.Z1, at + " z1");
            Assert.AreEqual((bool)expected["perfect"], actual.Perfect, at + " perfect");
            Assert.AreEqual((int)expected["combo"], actual.Combo, at + " combo");
            Assert.AreEqual((int)expected["gained"], actual.Gained, at + " gained");
        }

        private static string KindName(StepKind kind)
        {
            switch (kind)
            {
                case StepKind.Place: return "place";
                case StepKind.Miss: return "miss";
                default: return "continue";
            }
        }
    }
}
